import { DatabaseSync } from 'node:sqlite';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { checksIn } from '../../../../packages/engine/src/shared/vocabulary.ts';
import { seed } from './seed.mjs';

const TYPES = {
  INTEGER: 'integer',
  TEXT: 'text',
  REAL: 'double precision',
  BOOLEAN: 'boolean',
  DATE: 'date',
  TIMESTAMP: 'timestamp without time zone',
};
const REFERENCES = { incident: 'INC-', change_request: 'CHG-', service_request: 'REQ-', purchase_order: 'PO-' };
const ident = (value) => `"${String(value).replaceAll('"', '""')}"`;
const qualified = (name) => `"public".${ident(name)}`;

function defaultSql(table, column) {
  const value = column.dflt_value;
  if (value === null) return '';
  const prefix = REFERENCES[table];
  if (column.name === 'reference' && prefix && value === `'${prefix}' || lower(hex(randomblob(4)))`) {
    return ` DEFAULT ('${prefix}' || replace(gen_random_uuid()::text, '-', ''))`;
  }
  if (column.type === 'BOOLEAN' && ['0', '1'].includes(value)) return ` DEFAULT ${value === '1' ? 'true' : 'false'}`;
  if (value === 'CURRENT_TIMESTAMP' || /^-?\d+(?:\.\d+)?$/.test(value) || /^'(?:[^']|'')*'$/.test(value)) return ` DEFAULT ${value}`;
  throw new Error(`Unsupported seed default on ${table}.${column.name}.`);
}

/** Derive only the schema shapes used by this example, rejecting unfamiliar ones. */
export function postgresFixture() {
  const directory = mkdtempSync(join(tmpdir(), 'tablewalk-atlas-postgres-'));
  let db;
  try {
    const file = seed(join(directory, 'fixture.db'));
    db = new DatabaseSync(file, { readOnly: true });
    const definitions = db
      .prepare("SELECT name, sql FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid")
      .all();
    const tables = definitions.map(({ name, sql }) => {
      const columns = db.prepare(`PRAGMA table_info(${ident(name)})`).all();
      if (
        columns.filter((column) => column.pk).length !== 1 ||
        columns[0].name !== 'id' ||
        columns[0].pk !== 1 ||
        columns[0].type !== 'INTEGER'
      ) {
        throw new Error(`Unsupported seed primary key on ${name}.`);
      }
      const foreignKeys = db.prepare(`PRAGMA foreign_key_list(${ident(name)})`).all();
      if (foreignKeys.some((key) => key.seq !== 0 || key.on_delete !== 'NO ACTION' || key.on_update !== 'NO ACTION')) {
        throw new Error(`Unsupported seed foreign key on ${name}.`);
      }
      const indexes = db
        .prepare(`PRAGMA index_list(${ident(name)})`)
        .all()
        .map((index) => {
          const fields = db
            .prepare(`PRAGMA index_info(${ident(index.name)})`)
            .all()
            .map((field) => field.name);
          if (index.partial || fields.some((field) => !field) || !['c', 'u'].includes(index.origin)) {
            throw new Error(`Unsupported seed index on ${name}.`);
          }
          return { name: index.name, unique: Boolean(index.unique), origin: index.origin, columns: fields };
        });
      const checks = checksIn(sql);
      const ddlColumns = columns.map((column) => {
        const type = TYPES[column.type];
        if (!type) throw new Error(`Unsupported seed type on ${name}.${column.name}.`);
        return column.pk
          ? `${ident(column.name)} integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY`
          : `${ident(column.name)} ${type}${column.notnull ? ' NOT NULL' : ''}${defaultSql(name, column)}`;
      });
      const unique = indexes.filter((index) => index.origin === 'u').map((index) => `UNIQUE (${index.columns.map(ident).join(', ')})`);
      const create = `CREATE TABLE ${qualified(name)} (${[...ddlColumns, ...unique, ...checks.map((check) => `CHECK (${check})`)].join(', ')});`;
      const data = db
        .prepare(`SELECT * FROM ${ident(name)} ORDER BY id`)
        .all()
        .map((row) =>
          columns.map((column) => {
            const value = row[column.name];
            if (column.type !== 'BOOLEAN' || value === null) return value;
            if (value !== 0 && value !== 1) throw new Error(`Invalid seed boolean on ${name}.${column.name}.`);
            return value === 1;
          }),
        );
      return { name, columns: columns.map((column) => column.name), create, foreignKeys, indexes, checks, data };
    });
    if (tables.length !== 26 || tables.reduce((sum, table) => sum + table.foreignKeys.length, 0) !== 53) {
      throw new Error('Atlas schema changed; review the PostgreSQL seed before proceeding.');
    }
    return tables;
  } finally {
    db?.close();
    rmSync(directory, { recursive: true, force: true });
  }
}

/** Accepts an already-connected client so transaction behavior is testable offline. */
export async function loadPostgresFixture(client, tables = postgresFixture()) {
  let transaction = false;
  try {
    await client.query('BEGIN');
    transaction = true;
    await client.query("SET LOCAL lock_timeout = '5s'");
    const lock = await client.query("SELECT pg_try_advisory_xact_lock(hashtext('tablewalk/service-atlas/public')) AS acquired");
    if (!lock.rows[0]?.acquired) throw new Error('Another Atlas seed is already running.');
    const namespace = await client.query("SELECT oid FROM pg_namespace WHERE nspname = 'public'");
    if (!namespace.rows.length) throw new Error('The public schema must exist before seeding.');
    const existing = await client.query(
      `
      SELECT 1 FROM pg_class WHERE relnamespace = $1
      UNION ALL SELECT 1 FROM pg_proc WHERE pronamespace = $1
      UNION ALL SELECT 1 FROM pg_type WHERE typnamespace = $1 LIMIT 1`,
      [namespace.rows[0].oid],
    );
    if (existing.rows.length) throw new Error('Refusing to seed: the public schema is not empty.');
    await client.query('SET LOCAL search_path = pg_catalog, public');
    await client.query(tables.map((table) => table.create).join('\n'));

    const constraints = tables.flatMap((table) =>
      table.foreignKeys.map(
        (key) =>
          `ALTER TABLE ${qualified(table.name)} ADD FOREIGN KEY (${ident(key.from)}) REFERENCES ${qualified(key.table)} (${ident(key.to)});`,
      ),
    );
    const indexes = tables.flatMap((table) =>
      table.indexes
        .filter((index) => index.origin === 'c')
        .map(
          (index) =>
            `CREATE ${index.unique ? 'UNIQUE ' : ''}INDEX ${ident(index.name)} ON ${qualified(table.name)} (${index.columns.map(ident).join(', ')});`,
        ),
    );
    await client.query([...constraints, ...indexes].join('\n'));

    // The fixture's table creation order is also its dependency order.
    for (const table of tables) {
      for (let offset = 0; offset < table.data.length; offset += 100) {
        const batch = table.data.slice(offset, offset + 100);
        const values = batch.map(
          (row, rowIndex) => `(${row.map((_, columnIndex) => `$${rowIndex * table.columns.length + columnIndex + 1}`).join(', ')})`,
        );
        await client.query(
          `INSERT INTO ${qualified(table.name)} (${table.columns.map(ident).join(', ')}) VALUES ${values.join(', ')}`,
          batch.flat(),
        );
      }
      await client.query(
        `SELECT setval(pg_get_serial_sequence($1, 'id'), COALESCE(MAX("id"), 1), COUNT(*) > 0) FROM ${qualified(table.name)}`,
        [`public.${table.name}`],
      );
    }
    const counts = await client.query(
      tables.map((table) => `SELECT '${table.name}' AS name, COUNT(*)::integer AS total FROM ${qualified(table.name)}`).join(' UNION ALL '),
    );
    if (tables.some((table) => counts.rows.find((row) => row.name === table.name)?.total !== table.data.length)) {
      throw new Error('PostgreSQL seed row counts do not match the Atlas fixture.');
    }
    const keys = await client.query("SELECT COUNT(*)::integer AS total FROM pg_constraint WHERE connamespace = $1 AND contype = 'f'", [
      namespace.rows[0].oid,
    ]);
    if (keys.rows[0]?.total !== 53) throw new Error('PostgreSQL seed foreign-key count does not match Atlas.');
    await client.query('COMMIT');
    transaction = false;
    return { tables: tables.length, foreignKeys: 53, rows: tables.reduce((sum, table) => sum + table.data.length, 0) };
  } catch (error) {
    if (transaction) {
      try {
        await client.query('ROLLBACK');
      } catch {
        /* Preserve the original failure. */
      }
    }
    throw error;
  }
}

export async function seedPostgres(url) {
  if (!url) throw new Error('PLANETSCALE_DATABASE_URL is required.');
  let client;
  try {
    const { Client } = await import('pg');
    client = new Client({
      connectionString: url,
      application_name: 'tablewalk-atlas-seed',
      connectionTimeoutMillis: 10_000,
      statement_timeout: 30_000,
    });
    await client.connect();
    return await loadPostgresFixture(client);
  } catch {
    throw new Error(
      'Atlas PostgreSQL seed failed. No existing data is replaced; check target emptiness, permissions and connection settings.',
    );
  } finally {
    try {
      await client?.end();
    } catch {
      /* Do not expose driver connection details. */
    }
  }
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  try {
    console.log(JSON.stringify(await seedPostgres(process.env.PLANETSCALE_DATABASE_URL)));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
